// Entrée : URL/chemin du document non structuré + schéma d'extraction imposé.
// Chaque champ est un objet { valeur, extrait_source } : le modèle doit restituer le passage
// exact du document d'où provient la valeur. La validation humaine devient une comparaison
// de secondes (valeur contre extrait) au lieu d'une relecture du document (§ 10.4.1, rang 2).
return [{ json: {
  source_doc: 'https://www.fhs.swiss/…/communique.pdf',
  indicator_id: 'H1',
  period: '2025',
  extraction_schema: {
    periode:          { valeur: '', extrait_source: '' },
    valeur_totale_chf:{ valeur: '', extrait_source: '' },
    variation_pct:    { valeur: '', extrait_source: '' },
    premier_marche:   { valeur: '', extrait_source: '' }
  },
  prompt: "Extrais exactement les valeurs suivantes du document fourni au format JSON strict. Pour CHAQUE champ, renvoie un objet {valeur, extrait_source} où extrait_source est la phrase ou le fragment EXACT du document d'où provient la valeur, recopié à l'identique. Si une valeur est absente du document, écris ABSENT dans les deux champs. N'utilise aucune autre source que le document. Une valeur sans extrait_source vérifiable sera rejetée."
} }];

// Contrôle de consistance : comparaison champ par champ des 3 extractions.
// La comparaison porte sur la VALEUR ; l'extrait source accompagne chaque valeur
// et est conservé pour l'affichage côte à côte en file de validation.
const items = $input.all().map(i => i.json);
const parsed = items.map(x => { try { return typeof x.extraction === 'object' ? x.extraction : JSON.parse(x.choices?.[0]?.message?.content || x.content?.[0]?.text || '{}'); } catch(e) { return {}; } });
const fields = Object.keys(parsed[0] || {});
let agree = 0;
const detail = {};
for (const f of fields) {
  const vals = parsed.map(p => String(p[f]?.valeur ?? p[f] ?? '').trim());
  const extraits = parsed.map(p => String(p[f]?.extrait_source ?? '').trim());
  const unanimous = vals.every(v => v === vals[0] && v !== '');
  const tous_sources = extraits.every(e => e !== '' && e !== 'ABSENT') || vals[0] === 'ABSENT';
  detail[f] = { values: vals, extraits_source: extraits, unanimous, tous_sources };
  if (unanimous && tous_sources) agree++;
}
const consensus_score = fields.length ? agree / fields.length : 0;
// Une valeur unanime mais sans extrait vérifiable ne compte pas comme consensus :
// l'accord sur une affirmation invérifiable n'est pas une preuve (§ 6.3).
return [{ json: { consensus_score, detail, unanimous: consensus_score === 1, extractions: parsed } }];
